//! 🏁️ Original finalization request custody and completed Report publication remain in the typed Store owner across turns.
use super::*;
use semio_framework_job::{StepContext,close_original_retained_step};
use store::os_store::original_replay_publication::OriginalReplayPublication;
impl<P,Mu> TimeTravelStoreState<P,Mu>where P:semio_framework_value::ToValue+store::os_store::serialization::ArtifactStoreSnapshot+Send+Sync+'static,Mu:semio_framework_value::ToValue+semio_framework_value::FromValue+protocol::Mutation<P>+protocol::OpBinary+protocol::OpText+Send+'static{
 /// 📏️ A request handoff moves only existing canonical metadata into this original preallocated Store-state slot.
 pub fn commit_request_demands()->RetirementDemand{RetirementDemand{copy_bytes:2*std::mem::size_of::<store::HistoryFinalization>()+std::mem::size_of::<bool>(),depth:1,..Default::default()}}
 /// 👁️ The actual Store must remain available while any original publisher or request continuation is retained.
 pub fn finalizing(&self)->bool{self.commit_request.is_some()||self.commit_publisher.is_some()||self.commit_receipt.is_some()||self.commit_outcome.is_some()||self.commit_failure.is_some()||!self.commit_request_close.is_empty()}
 /// 🎟️ Captures the original effect request under the original caller; expensive semantic birth waits for maintenance.
 pub fn commit_finished(&mut self,store:&mut ArtifactStore<P,Mu>,request:&mut Option<store::HistoryFinalization>,actor:Option<&str>,cx:&mut StepContext<'_>)->Result<TimeTravelCommit,Fault>{
  if self.finalizing()||request.is_none(){return Err(ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"completed replay finalization request destination is occupied").into_fault())}let invalid_actor=actor.is_some_and(|actor|actor!=store.local_actor_id().0.as_str());let cancelled=cx.is_cancelled();let d=Self::commit_request_demands();let step=cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|_|{self.commit_request=request.take();self.commit_stage=0;self.commit_closing=cancelled||invalid_actor;self.commit_outcome=invalid_actor.then_some(TimeTravelCommit::Failed);Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})).map_err(|failure|{self.commit_failure=Some(failure);self.commit_closing=true;ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"original finalization request retained its complete admission failure").into_fault()})?;if step.progress().copied_items==0{return Ok(TimeTravelCommit::Pending)}Ok(TimeTravelCommit::Pending)
 }
 /// 📏️ A contextual close quotes the actual retained publisher and the exact original Store ledgers it returns.
 pub fn commit_close_demands(&self,store:&ArtifactStore<P,Mu>,body:usize)->Result<RetirementDemand,ValueError>{if let Some(owner)=self.commit_publisher.as_ref(){return if owner.terminal_is_empty(){Ok(OriginalReplayPublication::<P,Mu>::boxed_release_demands())}else{owner.close_demands(store,body)}}let owner=&self.commit_request_close;if !owner.is_empty(){return owner.demands(body)}if self.commit_request.is_some(){return owner.next_owner_demands::<store::HistoryFinalization>(true,&None,body)}if self.commit_failure.is_some(){return owner.next_owner_demands::<semio_framework_job::OriginalTurnFailure>(true,&None,body)}Ok(RetirementDemand{copy_bytes:std::mem::size_of::<TimeTravelCommit>()+std::mem::size_of::<bool>(),depth:1,..Default::default()})}
 /// 🧯️ Retains the complete original refusal without replacing an earlier source or converting its cause.
 pub fn retain_commit_failure(&mut self,failure:semio_framework_job::OriginalTurnFailure)->Result<(),semio_framework_job::OriginalTurnFailure>{if self.commit_failure.is_some(){return Err(failure)}self.commit_failure=Some(failure);self.commit_closing=true;self.commit_outcome=Some(TimeTravelCommit::Failed);Ok(())}
 /// ♻️ A cancelled authored replay enters the same actual typed retirement queue under its original decoder.
 pub fn retire_authoring_replay(&mut self,store:&mut ArtifactStore<P,Mu>,replay:&mut Option<store::os_store::snapshot_read::ArtifactDerivedReplay<P,Mu>>,cx:&mut StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if replay.is_none(){return Ok(true)}if self.retirements.len()==self.retirements.capacity(){let bytes=(self.retirements.len()+1)*std::mem::size_of::<Box<dyn semio_framework_value::ErasedSnapshotRetirement>>();let release=self.retirements.capacity()*std::mem::size_of::<Box<dyn semio_framework_value::ErasedSnapshotRetirement>>();let d=RetirementDemand{capacity_bytes:bytes,release_bytes:release,depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{self.retirements.try_reserve_exact(1).map_err(|_|ValueError::literal(semio_framework_value::ValueRefusalKind::AllocationFailed,"original undo retirement queue refused"))?;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,retained_capacity_bytes:bytes,released_bytes:release,..Default::default()}))})?;return Ok(false)}let grant=cx.retained_grant();let result=cx.with_native_retirement(|control|store.retire_derived_report_replay_controlled(replay,grant,control))?;let p=match result{Some((owner,p))=>{self.retirements.push_back(owner);p},None=>replay.as_mut().map_or(Default::default(),|replay|replay.take_preparation_receipt())};cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64);Ok(replay.is_none())}
 /// 🧳️ Undo and redo retain their own original completed Report until the same genuine publisher captures it.
 pub fn commit_report(&mut self,store:&ArtifactStore<P,Mu>,result:&mut Option<store::os_store::replay::EditReplayResult<P,Mu>>,request:&mut Option<store::HistoryFinalization>,cx:&mut StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if self.finalizing(){return Err(ValueError::literal(semio_framework_value::ValueRefusalKind::WorkLimit,"original time-travel publisher is already occupied").into())}let ready=OriginalReplayPublication::admit(store,result,request,cx,&mut self.commit_publisher)?;if ready{self.commit_stage=1;self.commit_closing=false;}Ok(ready)}
 /// 🪡️ Every preparation, visible decision, acknowledgement and physical return uses the actual current original Job context.
 pub fn step_commit(&mut self,store:&mut ArtifactStore<P,Mu>,cx:&mut StepContext<'_>)->Result<TimeTravelCommit,semio_framework_job::OriginalTurnFailure>{
  if self.commit_publisher.as_ref().is_some_and(|owner|!owner.matches_caller(cx)){return Err(ValueError::literal(semio_framework_value::ValueRefusalKind::OwnershipLimit,"native finalization requires its same original caller and decoder recipient").into())}
  let result=(||->Result<TimeTravelCommit,semio_framework_job::OriginalTurnFailure>{
   if !self.finalizing(){return Ok(TimeTravelCommit::Pending)}if cx.is_cancelled(){self.commit_closing=true;}
   if self.commit_closing{return cx.with_original_retirement(|cx|self.close_commit(store,cx))}
   match self.commit_stage{
    0=>{let result=OriginalReplayPublication::admit(store,&mut self.finished,&mut self.commit_request,cx,&mut self.commit_publisher);match result{Ok(true)=>self.commit_stage=1,Ok(false)=>{},Err(failure)=>{if failure.retained_progress()!=Default::default(){return Err(failure)}self.commit_failure=Some(failure);self.commit_outcome=Some(if self.finished.as_ref().is_some_and(|finished|finished.revision!=store.content_revision()){TimeTravelCommit::Stale}else{TimeTravelCommit::Blocked});self.commit_closing=true;}}},
    1=>{if self.commit_publisher.as_mut().unwrap().advance(store,cx)?{self.commit_stage=2;}},
    2=>{if self.commit_publisher.as_mut().unwrap().publish(store,cx)?{self.commit_stage=3;}},
    3=>{if self.commit_publisher.as_mut().unwrap().take_receipt(cx,&mut self.commit_receipt)?{self.commit_stage=4;}},
    4=>{if self.commit_publisher.as_mut().unwrap().acknowledge(cx)?{self.commit_stage=5;self.commit_closing=true;}},
    _=>return Err(ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"completed replay original driver phase changed").into()),
   }Ok(TimeTravelCommit::Pending)
  })();match result{Ok(outcome)=>Ok(outcome),Err(failure)=>{self.commit_failure=Some(failure);self.commit_closing=true;self.commit_outcome=Some(TimeTravelCommit::Failed);Ok(TimeTravelCommit::Pending)}}
 }
 fn close_commit(&mut self,store:&mut ArtifactStore<P,Mu>,cx:&mut StepContext<'_>)->Result<TimeTravelCommit,semio_framework_job::OriginalTurnFailure>{
  if let Some(owner)=self.commit_publisher.as_mut(){if !owner.terminal_is_empty(){owner.close_step(store,cx)?;}else{let d=OriginalReplayPublication::<P,Mu>::boxed_release_demands();close_original_retained_step(cx,d,|_|{self.commit_publisher=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;}return Ok(TimeTravelCommit::Pending)}
  if !self.commit_request_close.is_empty(){let owner=&mut self.commit_request_close;let d=owner.demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|owner.step_granted(grant))?;return Ok(TimeTravelCommit::Pending)}
  if self.commit_request.is_some(){let d=self.commit_request_close.next_owner_demands::<store::HistoryFinalization>(true,&None,cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|Ok(self.commit_request_close.begin_granted(&mut self.commit_request,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;return Ok(TimeTravelCommit::Pending)}
  if self.commit_failure.is_some(){let d=self.commit_request_close.next_owner_demands::<semio_framework_job::OriginalTurnFailure>(true,&None,cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|Ok(self.commit_request_close.begin_granted(&mut self.commit_failure,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;return Ok(TimeTravelCommit::Pending)}
  let d=RetirementDemand{copy_bytes:std::mem::size_of::<TimeTravelCommit>()+std::mem::size_of::<bool>(),depth:1,..Default::default()};let mut outcome=TimeTravelCommit::Pending;close_original_retained_step(cx,d,|_|{outcome=self.commit_receipt.take().map_or_else(||self.commit_outcome.take().unwrap_or(TimeTravelCommit::Failed),|receipt|TimeTravelCommit::Finalized{receipt});self.commit_outcome=None;self.commit_closing=false;self.commit_stage=0;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(outcome)
 }
}
